// Extrae texto y chat del update de Telegram y calcula fechas de referencia en Córdoba
// (hoy e inicio de semana/mes/año) para que Claude resuelva los períodos de las consultas.
// Comandos (/start, /help) y mensajes sin texto (fotos, audios) salen con texto vacío
// y reciben el mensaje de ayuda sin pasar por Claude.
const hoy = $now.setZone('America/Argentina/Cordoba');
const f = d => d.toFormat('dd-MM-yyyy');
const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const TIPOS = ['photo', 'voice', 'audio', 'video', 'document', 'sticker', 'location', 'contact'];

const salida = [];
for (const item of $input.all()) {
  const m = item.json.message;
  if (!m || !m.chat) continue;

  const textoCrudo = typeof m.text === 'string' ? m.text.trim() : '';
  salida.push({
    json: {
      texto: textoCrudo.startsWith('/') ? '' : textoCrudo,
      tipo_mensaje: textoCrudo ? 'text' : (TIPOS.find(t => m[t]) || 'otro'),
      chat_id: m.chat.id,
      nombre: (m.from && m.from.first_name) || '',
      message_id: m.message_id,
      fecha_hoy: f(hoy),
      dia_semana: DIAS[hoy.weekday - 1],
      inicio_semana: f(hoy.startOf('week')),
      inicio_mes: f(hoy.startOf('month')),
      inicio_anio: f(hoy.startOf('year')),
    },
  });
}

return salida;

// Limpia la respuesta de Claude (bloques markdown, texto extra) y la parsea de forma segura.
// Si algo no cierra, marca el mensaje como INVALIDO en vez de romper el flujo.
const origen = $('Extraer datos del mensaje').item.json;
const r = $json;

let crudo = '';
if (typeof r.merged_response === 'string') crudo = r.merged_response;
else if (Array.isArray(r.content)) crudo = r.content.filter(c => c && c.type === 'text').map(c => c.text).join('\n');
else if (typeof r.text === 'string') crudo = r.text;
else if (typeof r.output === 'string') crudo = r.output;

let limpio = String(crudo).replace(/```(?:json)?/gi, '').trim();
const ini = limpio.indexOf('{');
const fin = limpio.lastIndexOf('}');
if (ini !== -1 && fin > ini) limpio = limpio.slice(ini, fin + 1);

let d = {};
let errorParseo = '';
try {
  d = JSON.parse(limpio);
  if (!d || typeof d !== 'object' || Array.isArray(d)) throw new Error('La respuesta no es un objeto JSON');
} catch (e) {
  d = {};
  errorParseo = e.message;
}

const CATEGORIAS = [
  'Alimentación / Supermercado', 'Salidas / Ocio', 'Servicios y Suscripciones', 'Salud y Deporte',
  'Farmacia', 'Transporte / Vehículo', 'Indumentaria / Compras', 'Vivienda / Hogar', 'Educación / Cursos',
  'Donaciones', 'Ingresos / Sueldo / Extras', 'Otros',
];
// Por si Claude devuelve la categoría con la aclaración entre paréntesis
const limpiarCategoria = s => String(s || '').replace(/s*(.*)s*$/, '').trim();
const esFecha = s => /^\d{2}-\d{2}-\d{4}$/.test(String(s || ''));

const tipoCrudo = String(d.tipo || '').toUpperCase().trim();
let tipo = ['GASTO', 'INGRESO', 'CONSULTA', 'SALDOS'].includes(tipoCrudo) ? tipoCrudo : 'INVALIDO';
const esMovimiento = t => t === 'GASTO' || t === 'INGRESO';

// Acepta número o texto tipo "15.000", "15.000,50" o "$ 2500"
let monto = d.monto;
if (typeof monto === 'string') {
  monto = monto.replace(/[^\d,.-]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
}
monto = Number(monto);
if (esMovimiento(tipo) && !(Number.isFinite(monto) && monto > 0)) tipo = 'INVALIDO';
monto = esMovimiento(tipo) ? Math.round(monto * 100) / 100 : 0;

const monedaCruda = String(d.moneda || '').toUpperCase();
const moneda = monedaCruda.includes('EUR') || monedaCruda.includes('€') ? 'EUR'
  : monedaCruda.includes('USD') ? 'USD' : 'ARS';
const fecha = esFecha(d.fecha) ? d.fecha : origen.fecha_hoy;
const categoriaCruda = limpiarCategoria(d.categoria);
const categoria = CATEGORIAS.includes(categoriaCruda) ? categoriaCruda : 'Otros';
const descripcion = String(d.descripcion || '').trim();
const metodoPago = String(d.metodo_pago || '').trim() || 'No especificado';

const consultaTipo = String(d.consulta_tipo || '').toUpperCase().trim();
const consultaCategoria = limpiarCategoria(d.consulta_categoria);
const consulta = tipo === 'CONSULTA' ? {
  desde: esFecha(d.consulta_desde) ? d.consulta_desde : origen.inicio_mes,
  hasta: esFecha(d.consulta_hasta) ? d.consulta_hasta : origen.fecha_hoy,
  tipo: ['GASTO', 'INGRESO', 'AMBOS'].includes(consultaTipo) ? consultaTipo : 'GASTO',
  categoria: CATEGORIAS.includes(consultaCategoria) ? consultaCategoria : '',
  titulo: String(d.consulta_titulo || '').trim() || 'el período',
} : null;

return {
  json: {
    fecha,
    tipo,
    monto,
    moneda,
    categoria,
    descripcion,
    metodo_pago: metodoPago,
    notas: String(d.notas || '').trim(),
    consulta,
    chat_id: origen.chat_id,
    texto_original: origen.texto,
    error_parseo: errorParseo,
    respuesta_cruda: crudo,
  },
};

// Suma los movimientos de la hoja que caen en el período pedido, separados por moneda
// (no se mezclan ARS, USD y EUR), y arma la respuesta para Telegram.
const q = $('Limpiar y parsear JSON').first().json;
const c = q.consulta;

const aDia = f => {
  const m = String(f || '').match(/^(\d{2})-(\d{2})-(\d{4})$/);
  return m ? Date.UTC(+m[3], +m[2] - 1, +m[1]) / 86400000 : null;
};
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = n => {
  try { return Number(n).toLocaleString('es-AR', { maximumFractionDigits: 2 }); } catch (e) { return String(n); }
};

const desde = aDia(c.desde);
const hasta = aDia(c.hasta);
const filas = $input.all().map(i => i.json).filter(f => f && f.Monto !== undefined && f.Monto !== '');
const dentro = filas.filter(f => {
  const dia = aDia(f.Fecha);
  if (dia === null || dia < desde || dia > hasta) return false;
  if (c.tipo !== 'AMBOS' && f.Tipo !== c.tipo) return false;
  if (c.categoria && f['Categoría'] !== c.categoria) return false;
  return true;
});

const sumar = tipo => {
  const t = {};
  dentro.filter(f => f.Tipo === tipo).forEach(f => {
    const m = f.Moneda || 'ARS';
    t[m] = (t[m] || 0) + (Number(f.Monto) || 0);
  });
  return t;
};
const linea = t => Object.keys(t).length
  ? Object.entries(t).map(([m, v]) => '$' + fmt(v) + ' ' + m).join(' · ')
  : '$0';

const gastos = sumar('GASTO');
const ingresos = sumar('INGRESO');
const rango = c.desde === c.hasta ? c.desde : c.desde + ' al ' + c.hasta;

let msg = '📊 <b>Resumen — ' + esc(c.titulo) + '</b>\n📅 ' + rango;
if (c.categoria) msg += '\n🏷️ ' + esc(c.categoria);

if (!dentro.length) {
  msg += '\n\nNo encontré movimientos en ese período.';
} else {
  msg += '\n';
  if (c.tipo !== 'INGRESO') msg += '\n💸 <b>Gastos:</b> ' + linea(gastos);
  if (c.tipo !== 'GASTO') msg += '\n💰 <b>Ingresos:</b> ' + linea(ingresos);
  if (c.tipo === 'AMBOS') {
    const monedas = [...new Set([...Object.keys(gastos), ...Object.keys(ingresos)])];
    msg += '\n⚖️ <b>Balance:</b> ' + monedas
      .map(m => '$' + fmt((ingresos[m] || 0) - (gastos[m] || 0)) + ' ' + m).join(' · ');
  }

  // Top 5 categorías de gasto por moneda
  if (c.tipo !== 'INGRESO' && !c.categoria) {
    Object.keys(gastos).forEach(m => {
      const porCat = {};
      dentro.filter(f => f.Tipo === 'GASTO' && (f.Moneda || 'ARS') === m).forEach(f => {
        const k = f['Categoría'] || 'Otros';
        porCat[k] = (porCat[k] || 0) + (Number(f.Monto) || 0);
      });
      const top = Object.entries(porCat).sort((a, b) => b[1] - a[1]).slice(0, 5);
      msg += '\n\n🏷️ <b>Gastos por categoría (' + m + '):</b>\n' +
        top.map(([k, v]) => '• ' + esc(k) + ': $' + fmt(v)).join('\n');
    });
  }

  msg += '\n\n🧾 ' + dentro.length + (dentro.length === 1 ? ' movimiento' : ' movimientos');
}

return [{ json: { mensaje: msg, chat_id: q.chat_id } }];

// Arma la respuesta de "¿cuánto tengo?" con la pestaña Saldos: una fila por moneda
// (ARS, USD, EUR), que nunca se suman entre sí.
const q = $('Limpiar y parsear JSON').first().json;
const filas = $input.all().map(i => i.json).filter(f => f && f.Moneda);

const dinero = (n, moneda) => (n < 0 ? '-$' : '$') +
  Math.abs(n).toLocaleString('es-AR', { minimumFractionDigits: Number.isInteger(n) ? 0 : 2, maximumFractionDigits: 2 }) + ' ' + moneda;
const aNumero = v => typeof v === 'number' ? v
  : Number(String(v || '').replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.')) || 0;
// Actualizado puede venir como texto DD-MM-YYYY o como número de serie de fecha de Sheets
const aDia = v => {
  if (typeof v === 'number') return Math.floor(v) - 25569;
  const m = String(v || '').match(/^(\d{2})-(\d{2})-(\d{4})$/);
  return m ? Date.UTC(+m[3], +m[2] - 1, +m[1]) / 86400000 : null;
};
const diaATexto = d => {
  const f = new Date(d * 86400000);
  return String(f.getUTCDate()).padStart(2, '0') + '-' + String(f.getUTCMonth() + 1).padStart(2, '0') + '-' + f.getUTCFullYear();
};

if (!filas.length) {
  return [{ json: { chat_id: q.chat_id, mensaje: '❌ No pude leer la pestaña Saldos. Probá de nuevo en unos minutos.' } }];
}

const ETIQUETAS = { ARS: '🇦🇷 Pesos', USD: '🇺🇸 Dólares', EUR: '🇪🇺 Euros' };
const ORDEN = ['ARS', 'USD', 'EUR'];
const moneda = f => String(f.Moneda).trim().toUpperCase();
const ordenadas = filas.slice().sort((a, b) => {
  const ia = ORDEN.indexOf(moneda(a)), ib = ORDEN.indexOf(moneda(b));
  return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
});

let msg = '💳 <b>¿Cuánto tengo?</b>\n\n' + ordenadas
  .map(f => '<b>' + (ETIQUETAS[moneda(f)] || moneda(f)) + ':</b> ' + dinero(aNumero(f.Saldo), moneda(f)))
  .join('\n');

const dias = filas.map(f => aDia(f.Actualizado)).filter(d => d !== null);
if (dias.length) msg += '\n\n🕒 Última actualización: ' + diaATexto(Math.max(...dias));

return [{ json: { chat_id: q.chat_id, mensaje: msg } }];
